cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

// Basic counts
console.log('========== ORDER SUMMARY ==========');
console.log('Total orders:', data.length);

// Status breakdown
const statuses = {};
data.forEach(r => { statuses[r.Status] = (statuses[r.Status]||0) + 1; });
console.log('\n--- By Status ---');
Object.entries(statuses).forEach(([k,v]) => console.log('  ' + k + ':', v));

// Customer breakdown
const customers = {};
data.forEach(r => { customers[r.Customer] = (customers[r.Customer]||0) + 1; });
console.log('\n--- By Customer (order count) ---');
Object.entries(customers).sort((a,b) => b[1]-a[1]).forEach(([k,v]) => console.log('  ' + k + ':', v));

// Revenue
const totals = data.map(r => r['Total Paid']);
const totalRevenue = totals.reduce((a,b) => a+b, 0);
const confirmedRevenue = data.filter(r => r.Status === 'confirmed').map(r => r['Total Paid']).reduce((a,b) => a+b, 0);
const cancelledRevenue = data.filter(r => r.Status === 'cancelled').map(r => r['Total Paid']).reduce((a,b) => a+b, 0);
console.log('\n--- Revenue ---');
console.log('  Total (all orders): \$' + totalRevenue);
console.log('  Confirmed orders:   \$' + confirmedRevenue);
console.log('  Cancelled orders:   \$' + cancelledRevenue);
console.log('  Average order value: \$' + (totalRevenue / data.length).toFixed(2));
console.log('  Min order: \$' + Math.min(...totals));
console.log('  Max order: \$' + Math.max(...totals));

// Date breakdown
const dates = {};
data.forEach(r => { dates[r.Date] = (dates[r.Date]||0) + 1; });
console.log('\n--- By Date ---');
Object.entries(dates).forEach(([k,v]) => console.log('  ' + k + ':', v + ' orders'));

// Popular items
const items = {};
data.forEach(r => {
  r.Items.split(', ').forEach(item => {
    items[item] = (items[item]||0) + 1;
  });
});
console.log('\n--- Most Popular Items ---');
Object.entries(items).sort((a,b) => b[1]-a[1]).forEach(([k,v]) => console.log('  ' + k + ':', v + 'x'));
"
